import math


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i, v in enumerate(a):
        prefix[i + 1] = prefix[i] + v

    # Lower convex hull of prefix-sum points, left to right.
    # Max slope from a right endpoint lands on this hull.
    hull: list[int] = []

    def cross(i: int, j: int, m: int) -> int:
        return (j - i) * (prefix[m] - prefix[j]) - (prefix[j] - prefix[i]) * (m - j)

    def slope_gt(l1: int, l2: int, r: int) -> bool:
        return (prefix[r] - prefix[l1]) * (r - l2) > (prefix[r] - prefix[l2]) * (r - l1)

    best_s = 0
    best_len = 1
    have = False

    def consider(l: int, r: int) -> None:
        nonlocal best_s, best_len, have
        s = prefix[r] - prefix[l]
        length = r - l
        if not have or s * best_len > best_s * length:
            best_s = s
            best_len = length
            have = True

    nxt = 0
    for r in range(k, n + 1):
        while nxt <= r - k:
            while len(hull) >= 2 and cross(hull[-2], hull[-1], nxt) <= 0:
                hull.pop()
            hull.append(nxt)
            nxt += 1
        lo = 0
        hi = len(hull) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if slope_gt(hull[mid + 1], hull[mid], r):
                lo = mid + 1
            else:
                hi = mid
        consider(hull[lo], r)

    g = math.gcd(best_s, best_len)
    return [best_s // g, best_len // g]
